# E43_summarise -- split / cross-fitted / full cavity tests, q = 2 and q = 3 (chi2_{G-2}), on E31's data; fingerprint vs E31;
# Internet-Ads split placebo (E35c's data). Writes results/E43_split_q3_summary.csv, E43_split_table.tex, E43_summary.log.
HERE <- dirname(normalizePath(sub("--file=", "", grep("--file=", commandArgs(), value = TRUE)[1]))); ROOT <- dirname(HERE); RES <- file.path(ROOT, "results")
d <- read.csv(file.path(RES, "E43_split_q3_perrep.csv")); d <- d[!duplicated(d[, c("cell", "rep")]), ]
o <- read.csv(file.path(RES, "E31_split_crossfit_perrep.csv")); m <- merge(d, o, by = c("cell", "rep"))
sink(file.path(RES, "E43_summary.log"), split = TRUE)
cat(sprintf("Fingerprint vs E31 (%d replicates): max |diff| full %.2g, split %.2g, cross %.2g; decisions at .05 that differ: %d\n", nrow(m),
            max(abs(m$full_q2 - m$full)), max(abs(m$split_q2 - m$split)), max(abs(m$cross_q2 - m$cross)),
            sum((m$full_q2 < .05) != (m$full < .05)) + sum((m$split_q2 < .05) != (m$split < .05)) + sum((m$cross_q2 < .05) != (m$cross < .05))))
cat(sprintf("missing values: %d\n", sum(is.na(d[, -(1:2)]))))
ORDER <- c("A_p5", "B_p40", "B_p100", "B_p160", "H5_k25_ar03", "prev08_k25", "lasso_sparse5_p2n", "A_cubic1", "B_p40_quad1", "B_p100_quad1")
LAB <- c(A_p5 = "A, fixed $p$", B_p40 = "B, $p/n = 0.10$", B_p100 = "B, $p/n = 0.25$", B_p160 = "B, $p/n = 0.40$", H5_k25_ar03 = "$p/n = 0.25$, correlation $0.3$",
         prev08_k25 = "$p/n = 0.25$, prevalence $0.08$", lasso_sparse5_p2n = "lasso, sparse, $p = 2n$", A_cubic1 = "A, fixed $p$, cubic",
         B_p40_quad1 = "B, $p/n = 0.10$, quadratic", B_p100_quad1 = "B, $p/n = 0.25$, quadratic")
TESTS <- c("full_q2", "full_q3", "split_q2", "split_q3", "cross_q2", "cross_q3")
tab <- do.call(rbind, lapply(ORDER, function(cc) { s <- d[d$cell == cc, ]; z <- data.frame(cell = cc, R = nrow(s))
  for (t in TESTS) { r <- mean(s[[t]] < .05); z[[t]] <- r; z[[paste0(t, "_se")]] <- sqrt(r * (1 - r) / nrow(s)) }
  for (k in c("full", "split", "cross")) { dd <- (s[[paste0(k, "_q3")]] < .05) - (s[[paste0(k, "_q2")]] < .05)
    z[[paste0(k, "_diff")]] <- mean(dd); z[[paste0(k, "_diff_se")]] <- sd(dd) / sqrt(nrow(s)) }
  z }))
write.csv(tab, file.path(RES, "E43_split_q3_summary.csv"), row.names = FALSE)
options(width = 250); print(tab[, c("cell", "R", TESTS, "full_diff", "split_diff", "split_diff_se", "cross_diff", "cross_diff_se")], digits = 3, row.names = FALSE)
L <- c("% generated by sims/E43_summarise.R -- E31 data, 500 replicates, G = 10, chi2_8 reference for every test",
       "\\begin{tabular}{lrrrrrr}", "\\toprule",
       " & \\multicolumn{2}{c}{full sample} & \\multicolumn{2}{c}{split} & \\multicolumn{2}{c}{cross-fitted} \\\\",
       "\\cmidrule(lr){2-3}\\cmidrule(lr){4-5}\\cmidrule(lr){6-7}", "Design & $q=2$ & $q=3$ & $q=2$ & $q=3$ & $q=2$ & $q=3$ \\\\", "\\midrule")
for (k in seq_len(nrow(tab))) { z <- tab[k, ]; if (z$cell == "A_cubic1") L <- c(L, "\\midrule")
  L <- c(L, sprintf("%s & %s \\\\", LAB[[z$cell]], paste(sprintf("%.3f", unlist(z[TESTS])), collapse = " & "))) }
L <- c(L, "\\bottomrule", "\\end{tabular}"); writeLines(L, file.path(RES, "E43_split_table.tex"))
fa <- file.path(RES, "E43_ads_split_q3_perrep.csv")
if (file.exists(fa)) { a <- read.csv(fa); a <- a[!duplicated(a$rep), ]; e35c <- read.csv(file.path(RES, "E35c_ads_split_perrep.csv"))
  ma <- merge(a, e35c, by = "rep")
  cat(sprintf("\nInternet-Ads split placebo, R = %d (fingerprint vs E35c: max |diff| split %.2g, cross %.2g)\n", nrow(a),
              max(abs(ma$split_q2 - ma$split)), max(abs(ma$cross_q2 - ma$cross))))
  for (t in c("split_q2", "split_q3", "cross_q2", "cross_q3")) { r <- mean(a[[t]] < .05); cat(sprintf("  %-9s size %.3f (%.3f)\n", t, r, sqrt(r * (1 - r) / nrow(a)))) } }
sink()
